/**
 * "Try a similar one": extra practice generated by code from the unit's own items.
 * Only the subject (and therefore the be-form) is swapped; verbs come from the unit; answers are computed
 * deterministically. Every generated item is flagged origin:"generated" and shown as "Extra practice".
 * Book items themselves are never altered.
 */
import type { Exercise, Item, Tile } from './types';
import { BE, joinBe, personOf, whyBe } from './spelling';

const SUBJECTS = ['I', 'He', 'She', 'They', 'We', 'You', 'It'];

function pickSubject(current: string, seed: number, allowIt: boolean): string {
  const pool = SUBJECTS.filter((s) => s.toLowerCase() !== current.toLowerCase() && (allowIt || s !== 'It'));
  // prefer a subject that needs a different be-form, so the drill is not a copy
  const different = pool.filter((s) => personOf(s) !== personOf(current));
  const list = different.length ? different : pool;
  return list[seed % list.length];
}

function baseVerb(item: Item): string | undefined {
  if (item.verb) return item.verb;
  const cue = item.cueWords?.replace(/[()?]/g, '').split('/').map((s) => s.trim()) ?? [];
  const ving = item.tiles?.find((t) => t.role === 'verb')?.t.toLowerCase();
  return cue.find((w) => ving && ving.startsWith(w.slice(0, Math.max(2, w.length - 1)).toLowerCase()));
}

export function similarItem(exercise: Exercise, item: Item, seed = 0): Item | null {
  const tiles = item.tiles ?? [];
  const subj = tiles.find((t) => t.role === 'subject');
  const verb = tiles.find((t) => t.role === 'verb');
  if (!subj || !verb) return null;
  const base = baseVerb(item) ?? verb.t;
  const animate = !['it', 'the weather'].includes(subj.t.toLowerCase());
  if (!animate) return null;
  const next = pickSubject(subj.t, seed, false);
  const p = personOf(next);
  const common = {
    number: item.number, isExample: false, origin: 'generated' as const, hints: { bn: '' },
    audio: { question: null, answer: null, pauseMs: 0 }, mapsToSection: item.mapsToSection, verb: base,
  };
  if (exercise.type === 'buildQuestion') {
    const lower = next === 'I' ? 'I' : next.toLowerCase();
    const newTiles: Tile[] = tiles.map((t) =>
      t.role === 'subject' ? { ...t, t: lower } : t.role === 'be' ? { ...t, t: /^[A-Z]/.test(t.t) ? cap(BE[p].full) : BE[p].full } : t);
    const answer = newTiles.map((t) => t.t).join(' ') + '?';
    const cue = `(${newTiles.filter((t) => t.role !== 'be').map((t) => (t.role === 'verb' ? base : t.t.toLowerCase() === 'i' ? 'I' : t.t.toLowerCase())).join(' / ')}?)`;
    return {
      ...common, id: `${item.id}~${seed}`, prompt: 'Same pattern, new subject.', cueWords: cue, pattern: item.pattern,
      acceptedAnswers: [answer], officialAnswer: answer, answerSentences: [answer], tiles: newTiles,
      why: `${whyBe(next)} In a question, be goes before the subject.`,
    };
  }
  const negative = item.polarity === 'negative';
  const forms = negative ? BE[p].neg : [BE[p].short, BE[p].full];
  const accepted = forms.map((f) => `${joinBe(next, f)} ${verb.t}`);
  return {
    ...common, id: `${item.id}~${seed}`,
    prompt: '______', cueWords: `${next} / ${base}`, polarity: item.polarity, subjectInBlank: true,
    clue: undefined, clueSpans: undefined,
    acceptedAnswers: accepted, officialAnswer: accepted.join(' / '), answerSentences: accepted,
    tiles: [{ t: next, role: 'subject' }, { t: forms[0], role: 'be' }, { t: verb.t, role: 'verb' }],
    why: `${whyBe(next)}${negative ? ' Negative = be + not.' : ''}`,
    spellingNote: item.spellingNote,
    structure: negative ? 'subject + be + not + verb-ing' : 'subject + be + verb-ing',
  };
}

const cap = (s: string) => s[0].toUpperCase() + s.slice(1);
